create or replace TABLE LDL_PRODUCTION_CLONE_GOOGLE_20260608_1030.P_LEW_MART_LIDL_DIGITAL.T_AGG_UNQ_CUST_LDPL_MTH_1 cluster by (CLIENT_ID)(
	ASPECT_ID NUMBER(38,0) NOT NULL COMMENT 'Gesellschaftsform (1 = Betriebs- 2 = Vertriebsgesellschaft)',
	CLIENT_ID NUMBER(38,0) NOT NULL COMMENT 'DWH-Mandant_1; FK auf CLIENT',
	CY_MONTH NUMBER(38,0) NOT NULL COMMENT 'Lidl+ : Month value (-1 means data is not at month level)',
	HARMO_CAL_MONTH_NO NUMBER(38,0) NOT NULL COMMENT 'Harmonized month no  per country_1 - month since rollout',
	MOVE_TO_STORE_ID NUMBER(38,0) NOT NULL COMMENT 'Lidl Store Id',
	WH_ID NUMBER(38,0) NOT NULL COMMENT 'Warehouse ID',
	CUSTOMER_SID NUMBER(38,0) NOT NULL COMMENT 'Surrogate Key CUSTOMER',
	LIDLPLUS_CUST_FG VARCHAR(1) NOT NULL COMMENT 'Lidl Plus Customer Flag',
	ADJUST_GROWTH_FG NUMBER(38,0) NOT NULL COMMENT 'Adjust growth flag - berenigte steigerung',
	MTH_RF_SEGMENT_SID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Recency-frequency segments id - used (client_id + loc_sid(LU), customer_sid, cy_month) to select t_cust_rfm_segment_mth.mth_rf_segment_sid',
	MTH_M_SEGMENT_SID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Monetary Segment Id - used (client_id + loc_sid(LU), customer_sid, cy_month) to select t_cust_m_segment_mth.mth_m_segment_sid',
	MTH_ST_SEGMENT_SID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'STRATEGIC Segment Id - used (client_id + loc_sid(LU), customer_sid, cy_month) to select t_cust_m_segment_mth.mth_m_segment_sid',
	MTH_FR_SEGMENT_SID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'FREQUENCY Segment Id - used (client_id + loc_sid(LU), customer_sid, cy_month) to select t_cust_m_segment_mth.mth_m_segment_sid',
	MTH_MO_SEGMENT_SID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'new Monetary Segment Id - used (client_id + loc_sid(LU), customer_sid, cy_month) to select t_cust_m_segment_mth.mth_m_segment_sid',
	MTH_RE_SEGMENT_SID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'RECENCY Segment Id - used (client_id + loc_sid(LU), customer_sid, cy_month) to select t_cust_m_segment_mth.mth_m_segment_sid',
	BUSYEAR_QTR_RF_SEGMENT_SID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Recency-frequency segments id - used (client_id + loc_sid(LU), customer_sid, cy_month) to select t_cust_rfm_segment_busyear_qtr.busyear_qtr_rf_segment_sid',
	BUSYEAR_QTR_M_SEGMENT_SID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Monetary Segment Id - used (client_id + loc_sid(LU), customer_sid, cy_month) to select t_cust_m_segment_busyear_qtr.busyear_m_segment_sid',
	CURRENCY_ISO_CD VARCHAR(3) NOT NULL COMMENT 'iso code for the clients (countrys) currency',
	CURR_TOT_ID NUMBER(38,0) NOT NULL COMMENT 'Fixe Werte fur EUR=0, GBP=40 sonst Client_Id',
	CM_CUST_ACT NUMBER(38,0) COMMENT 'Current Month Customer Active flag 1 for active 0 for not active',
	PM_CUST_ACT NUMBER(38,0) COMMENT 'Previous Month Customer Active flag 1 for active 0 for not active',
	PYM_CUST_ACT NUMBER(38,0) COMMENT 'Previous Year Month Customer Active flag 1 for active 0 for not active',
	CM_MTH_STR_OPEN_FG NUMBER(38,0) COMMENT 'Store open flag : Current month',
	CM_RCPTS_CNT NUMBER(38,0) COMMENT 'Receipts count : Current month',
	PM_MTH_STR_OPEN_FG NUMBER(38,0) COMMENT 'Store open flag : Previous month',
	PM_RCPTS_CNT NUMBER(38,0) COMMENT 'Receipts count : Previous month',
	PYM_MTH_STR_OPEN_FG NUMBER(38,0) COMMENT 'Store open flag : Previous year month',
	PYM_RCPTS_CNT NUMBER(38,0) COMMENT 'Receipts count : Previous year month',
	LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'Load identifier',
	DWH_CREATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Row create time',
	DWH_UPDATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Row update time',
	constraint PK_UNQ_CUST_LDPL_MTH primary key (ASPECT_ID, CLIENT_ID, CY_MONTH, MOVE_TO_STORE_ID, CUSTOMER_SID, ADJUST_GROWTH_FG, CURRENCY_ISO_CD)
)COMMENT='Table for Unique customer every Month'
;
